import { test, expect, Page } from '@playwright/test';
import path from 'path';

const fixtures = path.join(__dirname, 'fixtures');
// Independent of the image fixtures generated by the main test file.
const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=', 'base64');
async function load(page: Page, files: string[]) {
  await page.locator('#multiFileInput').setInputFiles(files.map(name => name.endsWith('.png')
    ? { name, mimeType:'image/png', buffer:png } : path.join(fixtures, name)));
  await expect(page.locator('#comparisonView')).toHaveClass(/active/);
  await page.waitForFunction(count => (window as any).getLoadedSlotCount() === count,files.length);
}
async function open(page: Page, type?: string) {
  await page.locator('#infoEditorButton').click();
  await expect(page.locator('#infoEditorDialog')).toBeVisible();
  if (type) await page.locator('#infoEditorType').selectOption(type);
}
async function close(page: Page) {
  await page.locator('#infoEditorClose').click();
  await expect(page.locator('#infoEditorDialog')).not.toBeVisible();
}
async function profile(page: Page, type: string) {
  return page.evaluate(t => JSON.parse(localStorage.getItem('pref_infoBarProfiles')!).profiles[t], type);
}
const field = (page: Page, id: string) => page.locator(`[data-info-toggle="${id}"]`);
async function dragBefore(page: Page, id: string, target: string) {
  await page.locator(`[data-element-id="${target}"]`).scrollIntoViewIfNeeded();
  await page.locator(`[data-info-drag="${id}"]`).dragTo(page.locator(`[data-element-id="${target}"]`),{targetPosition:{x:60,y:3}});
}

test.beforeEach(async ({ page }) => {
  await page.addInitScript(() => localStorage.setItem('lastSeenVersion','999.0.0'));
  await page.goto('/');
});

test('default stays unchanged; presets keep their name and Reset restores the original bars', async ({ page }) => {
  expect(await page.evaluate(() => (window as any).__testAPI.infoBarProfiles.video.preset)).toBe('default');
  await load(page, ['landscape_a.mp4','landscape_b.mp4']);
  await expect(page.locator('.asset-audio-format:not(:empty)').first()).toContainText('AAC');
  await expect(page.locator('.info-custom')).toHaveCount(0);
  await open(page, 'video');
  const rect = await page.locator('#infoEditorDialog').boundingBox();
  expect(rect!.x).toBeGreaterThan(20);
  expect(rect!.y).toBeGreaterThanOrEqual(15);
  for (const preset of ['minimal','visual','audio','all']) {
    await page.locator('#infoEditorPreset').selectOption(preset);
    await expect(page.locator('#infoEditorPreset')).toHaveValue(preset);
    expect((await profile(page,'video')).preset).toBe(preset);
  }
  await page.locator('#infoEditorReset').click();
  await expect(page.locator('#infoEditorPreset')).toHaveValue('default');
  await close(page);
  await expect(page.locator('.info-custom')).toHaveCount(0);
  await expect(page.locator('.asset-audio-format:not(:empty)').first()).toBeVisible();
  await expect(page.locator('.asset-audio-format:not(:empty)').first()).toContainText('AAC');
});

test('field order and typography apply to Stack and Grid without changing playback', async ({ page }) => {
  await load(page, ['landscape_a.mp4','landscape_b.mp4']);
  await open(page, 'video');
  await page.locator('#infoEditorPreset').selectOption('visual');
  await page.locator('[data-info-select="duration"]').click();
  await page.locator('#infoEditorSize').selectOption('14');
  await page.locator('#infoEditorBold').check();
  await page.locator('#infoEditorColor').evaluate((element: HTMLInputElement) => {
    element.value = '#44aaff'; element.dispatchEvent(new Event('input',{bubbles:true}));
  });
  await dragBefore(page,'duration','fps');
  await close(page);
  const bars = page.locator('.asset-info-bar.info-custom');
  await expect(bars).toHaveCount(2);
  await expect(bars.first().locator('.info-field-duration')).toHaveCSS('font-size','14px');
  await expect(bars.first().locator('.info-field-duration')).toHaveCSS('font-weight','700');
  await expect(bars.first().locator('.info-field-duration')).toHaveCSS('color','rgb(68, 170, 255)');
  const gridOrder = await bars.first().locator('.info-items [data-info-kind="field"]').evaluateAll(items => items.map(item => (item as HTMLElement).dataset.infoId));
  expect(gridOrder.indexOf('duration')).toBeLessThan(gridOrder.indexOf('fps'));
  await page.keyboard.press('s');
  await expect(page.locator('#stackInfoStrip')).toHaveClass(/info-custom/);
  await expect(page.locator('#stackInfoStrip .info-field-duration')).toHaveCSS('color','rgb(68, 170, 255)');
  const stackOrder = await page.locator('#stackInfoStrip .info-items [data-info-kind="field"]').evaluateAll(items => items.map(item => (item as HTMLElement).dataset.infoId));
  expect(stackOrder).toEqual(gridOrder);
  expect(await page.locator('.asset-layer video').evaluateAll(videos => videos.every(video => (video as HTMLVideoElement).paused))).toBe(true);
});

