test('another tab updates the active profile and failed storage is explained', async ({ page, context }) => {
  await load(page, ['landscape_a.mp4']);
  const second = await context.newPage(); await second.goto('/');
  await open(second, 'video'); await second.locator('#infoEditorPreset').selectOption('minimal');
  await expect(page.locator('#stackInfoStrip .info-items [data-info-kind="field"]')).toHaveCount(1);
  await expect(page.locator('#stackInfoStrip .info-field-duration')).toBeVisible();
  await second.close();
  await open(page, 'video');
  await page.evaluate(() => {
    const original = Storage.prototype.setItem;
    Storage.prototype.setItem = function(key,value) { if (key === 'pref_infoBarProfiles') throw new DOMException('Blocked','QuotaExceededError'); original.call(this,key,value); };
  });
  await page.locator('#infoEditorPreset').selectOption('visual');
  await expect(page.locator('#infoEditorStatus')).toHaveAttribute('role','alert');
  await expect(page.locator('#infoEditorStatus')).toContainText('could not be saved');
  expect(await page.evaluate(() => (window as any).__testAPI.infoBarProfiles.video.preset)).toBe('visual');
  expect((await profile(page,'video')).preset).toBe('minimal');
  await close(page);
  await expect(page.locator('#stackInfoStrip .info-field-resolution')).toBeVisible();
});

