test('left and right sections anchor Zoom, preserve styles and survive reload in Stack and Grid', async ({ page }) => {
  await load(page,['landscape_a.mp4','landscape_b.mp4']);
  await open(page,'video'); await page.locator('#infoEditorPreset').selectOption('all');
  await expect(page.locator('[data-info-section="right"] [data-element-id="zoom"]')).toHaveCount(1);
  await page.locator('[data-info-select="zoom"]').click();
  await expect(page.locator('#infoEditorAlign')).toHaveValue('right');
  await page.locator('#infoEditorBold').check();
  await page.locator('#infoEditorSize').selectOption('14');
  await close(page);
  await expect.poll(() => page.locator('.asset-info-bar.info-custom').evaluateAll(bars => bars.every(bar => {
    const zoom = bar.querySelector('.info-section-right .info-field-zoom') as HTMLElement;
    return zoom && !zoom.hidden && Math.abs(zoom.getBoundingClientRect().right - bar.getBoundingClientRect().right + parseFloat(getComputedStyle(bar).paddingRight)) < 1;
  }))).toBe(true);
  await page.locator('#stackIconBtn').click();
  for (const width of [320,736,1280]) {
    await page.setViewportSize({width,height:736});
    const zoom = page.locator('#stackInfoStrip .info-section-right .info-field-zoom');
    await expect(zoom).toBeVisible(); await expect(zoom).toHaveCSS('font-weight','700');
    await expect.poll(() => page.evaluate(() => {
      const strip = document.getElementById('stackInfoStrip')!, element = strip.querySelector('.info-section-right .info-field-zoom');
      return !!element && Math.abs(element.getBoundingClientRect().right - strip.getBoundingClientRect().right) < 1;
    })).toBe(true);
  }
  const saved = await profile(page,'video');
  await page.reload();await open(page,'video');await page.locator('[data-info-select="zoom"]').click();
  await expect(page.locator('#infoEditorAlign')).toHaveValue('right');
  expect(await profile(page,'video')).toEqual(saved);
  await page.locator('#infoEditorAlign').selectOption('left');
  await expect(page.locator('[data-info-section="left"] [data-element-id="zoom"]')).toHaveCount(1);
  await expect(page.locator('#infoEditorPreview .info-section-right .info-field-zoom')).toHaveCount(0);
  await expect(page.locator('#infoEditorPreview .info-section-left .info-field-zoom')).toHaveCSS('font-weight','700');
});

test('each section orders its fields and spacers independently and supports drag transfers', async ({ page }) => {
  await open(page,'video');await page.locator('#infoEditorPreset').selectOption('minimal');
  await page.locator('[data-info-select="fps"]').click();await field(page,'fps').check();
  await page.locator('#infoEditorAlign').selectOption('right');
  await page.locator('#infoEditorAddSpacer').click();
  await expect(page.locator('#infoEditorAlign')).toHaveValue('right');
  await page.locator('#infoEditorSpacerWidth').fill('48');
  await field(page,'zoom').check();
  await expect(page.locator('#infoEditorPreview .info-section-right .info-gap')).toHaveCSS('width','48px');
  await expect(page.locator('#infoEditorPreview .info-section-left .info-gap')).toHaveCount(0);
  const durationBefore = (await profile(page,'video')).elements.find((item: any) => item.id === 'duration');
  await dragBefore(page,'zoom','gap-1');
  const rightOrder = await page.locator('[data-info-section="right"] [data-element-id]').evaluateAll(rows => rows.map(row => (row as HTMLElement).dataset.elementId));
  expect(rightOrder).toEqual(['fps','zoom','gap-1']);
  expect((await profile(page,'video')).elements.find((item: any) => item.id === 'duration')).toEqual(durationBefore);
  await expect(page.locator('#infoEditorPreview .info-gap')).toHaveCount(0);
  await dragBefore(page,'duration','fps');
  await expect(page.locator('[data-info-section="right"] [data-element-id="duration"]')).toHaveCount(1);
  await expect(page.locator('[data-info-section="left"] [data-element-id="duration"]')).toHaveCount(0);
  // A section can also accept a drag when it has no rows.
  await page.locator('#infoEditorType').selectOption('image');
  await page.locator('[data-info-select="zoom"]').click();await page.locator('#infoEditorAlign').selectOption('left');
  await page.locator('[data-info-drag="zoom"]').dragTo(page.locator('[data-info-section="right"]'));
  await expect(page.locator('[data-info-section="right"] [data-element-id="zoom"]')).toHaveCount(1);
});

test('portrait Grid cells retain identity, Zoom and selected overflow through narrow and short resizes', async ({ page }) => {
  await open(page,'video');await page.locator('#infoEditorPreset').selectOption('all');
  await page.locator('#infoEditorAudio').uncheck();await close(page);
  await load(page,Array(4).fill('portrait.mp4'));
  for (const [width,height] of [[320,736],[320,400],[736,400],[1280,720]]) {
    await page.setViewportSize({width,height});
    await expect.poll(() => page.locator('.asset-info-bar.info-custom').evaluateAll(bars => bars.length === 4 && bars.every(bar => {
      const bounds = bar.getBoundingClientRect(), cell = bar.closest('.asset-layer')!.getBoundingClientRect();
      const picture = bar.parentElement!.getBoundingClientRect();
      const controls = [bar.querySelector('.asset-name'),bar.querySelector('.info-more'),bar.querySelector('.info-field-zoom')] as HTMLElement[];
      return bounds.left >= cell.left-1 && bounds.right <= cell.right+1 && bounds.bottom <= picture.top+1 && picture.width > 0 && picture.height > 0 && controls.every(control => control && !control.hidden && control.getBoundingClientRect().left >= bounds.left && control.getBoundingClientRect().right <= bounds.right+1);
    }))).toBe(true);
    const bars = page.locator('.asset-info-bar.info-custom');
    for (let index=0;index<4;index++) {
      await bars.nth(index).locator('.info-more').click();
      await expect(page.locator('#infoOverflowPanel')).toBeVisible();
      await expect(page.locator('#infoOverflowValues .info-field-audioCodec, #infoOverflowValues .info-field-channels')).toHaveCount(0);
      await expect(page.locator('#infoOverflowValues .info-item')).not.toHaveCount(0);
      await page.keyboard.press('Escape');await expect(bars.nth(index).locator('.info-more')).toBeFocused();
    }
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  }
  await page.setViewportSize({width:320,height:400});
  await page.locator('.asset-info-bar .asset-name').first().click();
  await expect(page.locator('.hidden-slot-pill')).toHaveCount(1);
});

test('older single-section profiles keep custom ordering and named presets migrate Zoom to the right', async ({ page }) => {
  await open(page,'video');await page.locator('#infoEditorPreset').selectOption('visual');await close(page);
  await page.evaluate(() => {
    const saved = JSON.parse(localStorage.getItem('pref_infoBarProfiles')!);
    for (const profile of Object.values(saved.profiles) as any[]) for (const item of profile.elements) delete item.align;
    // A custom image profile keeps its legacy left-to-right order.
    saved.profiles.image.preset = 'custom';saved.profiles.image.elements.reverse();
    localStorage.setItem('pref_infoBarProfiles',JSON.stringify(saved));
  });
  await page.reload();await open(page,'video');
  await expect(page.locator('#infoEditorPreset')).toHaveValue('visual');
  await expect(page.locator('[data-info-section="right"] [data-element-id="zoom"]')).toHaveCount(1);
  await page.locator('#infoEditorType').selectOption('image');
  await expect(page.locator('[data-info-section="right"] [data-element-id]')).toHaveCount(0);
  expect(await page.locator('[data-info-section="left"] [data-element-id]').first().getAttribute('data-element-id')).toBe('fileSize');
});

