  await load(page,['one.png','two.png']);await open(page,'image');
  await expect(page.locator('.info-editor-move')).toHaveCount(0);
  await page.locator('[data-info-drag="resolution"]').focus();await page.keyboard.press('ArrowUp');
  await expect(page.locator('#infoEditorPreset')).toHaveValue('default');
  expect(await page.evaluate(()=>localStorage.getItem('pref_infoBarProfiles'))).toBeNull();
  const handle = page.locator('[data-info-drag="aspect"]');await handle.focus();
  await page.keyboard.press('ArrowUp');await expect(handle).toBeFocused();
  expect((await profile(page,'image')).elements.filter((item:any)=>item.align==='left').map((item:any)=>item.id).slice(0,2)).toEqual(['aspect','resolution']);
  await page.keyboard.press('ArrowRight');await expect(handle).toBeFocused();
